    I=G[f'Demo pair {n} input']; O=G[f'Demo pair {n} output']
    try:
        R=solve_debug(I)
        nd=sum(R[r][c]!=O[r][c] for r in range(len(O)) for c in range(len(O[0])))
        print(n,'ndiff',nd)
    except Exception as e:
