import traceback
def solve_debug(I):
    h,w=len(I),len(I[0])
    bgv=Counter(x for r in I for x in r).most_common(1)[0][0]
    comps=[list(c) for c in components(I,bgv)]
    multis=[c for c in comps if len(c)>1]; singles=[next(iter(c)) for c in comps if len(c)==1]
    variants=[]
    for t in multis:
        b=bboxmap(t,I)
        for nm,tr in TRANS.items():
            variants.append((nm,transform_map(b,tr)))
    R=[[r[:] for r in I]]
    for mi,m in enumerate(singles):
        try:
            mv=I[m[0]][m[1]]
            cands=[]
            for nm,vb in variants:
                ancs=[off for off,vv in vb.items() if vv==mv]
                for ar,ac in ancs:
                    dr,dc=m[0]-ar,m[1]-ac
                    good=True
                    for (a,b_),vv in vb.items():
                        rr,cc=a+dr,b_+dc
                        if not(0<=rr<h and 0<=cc<w) or ((rr,cc)!=m and I[rr][cc]!=bgv): good=False;break
                    if good: cands.append((abs(dr)+abs(dc),nm,(ar,ac),(dr,dc),vb))
            if not cands: continue
            _,nm,anc,(dl,dv),vb=min(cands)
            for (a,b_),vv in vb.items():
                rr,cc=a+dl,b_+dv
                assert 0<=rr<h and 0<=cc<w,('demo',1,'marker',m,'cell',(rr,cc),'rel',(a,b_))
                if I[rr][cc]==bgv: R[rr][cc]=vv
        except Exception as e:
            print('fail at marker',m,'idx',mi,'e',e); traceback.print_exc(); return R
    return R
solve_debug(G['Demo pair 1 input'])
